require __DIR__.'/app/bootstrap.php';$user=require_permission('manage_staff');$id=positive_id($_GET,'id');$row=$id?staff_record($id):array_fill_keys(STAFF_FIELDS,'');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();try{$saved=save_employee($id?:null,$user);flash($id?'Employee profile and history updated.':'Employee added to the directory.');redirect('employee.php?id='.$saved);}catch(InvalidArgumentException $e){$error=$e->getMessage();}
}
$value=function(string $key,string $default='')use($row):string{return $_SERVER['REQUEST_METHOD']==='POST'?request_string($_POST,$key):(string)($row[$key]??$default);};
page_start($id?'Edit employee':'Add employee',$user);?><a class="back-link" href="<?=$id?'employee.php?id='.$id:'staff.php'?>">← Back to <?=$id?'profile':'directory'?></a><section class="panel"><div class="section-head"><div><h2><?=$id?'Update their next chapter':'Create an employee profile'?></h2><p class="muted">Required fields are marked *. Every save adds an entry to staff history.</p></div></div><?php error_notice($error);?><form method="post"><?php csrf_field();?><input type="hidden" name="version" value="<?=e($value('version','1'))?>"><div class="form-grid"><label>Employee code *<input name="employee_code" required maxlength="40" value="<?=e($value('employee_code'))?>"></label><label>Full name *<input name="full_name" required maxlength="150" value="<?=e($value('full_name'))?>"></label><label>Position *<input name="position" required maxlength="150" value="<?=e($value('position'))?>"></label><label>Shift schedule and timezone *<input name="shift_schedule" required maxlength="190" placeholder="Mon–Fri, 8 AM–5 PM, Asia/Manila" value="<?=e($value('shift_schedule'))?>"></label><label>Department *<select name="department_id" required><option value="">Select department</option><?php options(active_departments(),$value('department_id'));?></select></label><label>Team *<input name="team_label" required maxlength="120" value="<?=e($value('team_label'))?>" list="teams"><datalist id="teams"><?php foreach(query('SELECT DISTINCT team_label FROM staff_directory ORDER BY team_label') as $team):?><option value="<?=e($team['team_label'])?>"><?php endforeach;?></datalist></label><label>Team leader *<select name="tl_id" required><option value="">Select team leader</option><?php options(tls(),$value('tl_id',$user['role_slug']==='team-leader'?(string)$user['id']:''),'full_name');?></select></label><label>Status *<select name="employment_status" required><?php enum_options(STAFF_STATUSES,$value('employment_status')?:'new');?></select></label><label>Start date *<input type="date" name="start_date" required value="<?=e($value('start_date'))?>"></label><label>Exit date (exited staff only)<input type="date" name="exit_date" max="<?=date('Y-m-d')?>" value="<?=e($value('exit_date'))?>"></label><label class="wide">Profile notes<textarea name="notes" maxlength="10000" rows="3"><?=e($value('notes'))?></textarea></label><label>Change effective date *<input name="effective_date" type="date" max="<?=date('Y-m-d')?>" required value="<?=e($value('effective_date',date('Y-m-d')))?>"></label><label>History note *<textarea name="history_note" rows="3" maxlength="10000" required placeholder="Explain the onboarding, transfer, shift change or exit."><?=e($value('history_note'))?></textarea></label></div><div class="form-footer"><button class="button"><?=$id?'Save profile & history':'Create employee'?></button><a class="button button-secondary" href="<?=$id?'employee.php?id='.$id:'staff.php'?>">Cancel</a></div></form></section><?php page_end();
